package com.shopsphere.model;import com.fasterxml.jackson.annotation.JsonIgnore;import jakarta.persistence.*;import java.time.LocalDateTime;@Entity @Table(name="app_users") public class AppUser{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false)private String name;@Column(nullable=false,unique=true)private String email;@JsonIgnore @Column(nullable=false)private String password;@Enumerated(EnumType.STRING)private Role role=Role.CUSTOMER;private LocalDateTime createdAt=LocalDateTime.now();public AppUser(){}public AppUser(String n,String e,String p,Role r){name=n;email=e;password=p;role=r;}public Long getId(){return id;}public String getName(){return name;}public void setName(String x){name=x;}public String getEmail(){return email;}public void setEmail(String x){email=x;}public String getPassword(){return password;}public void setPassword(String x){password=x;}public Role getRole(){return role;}public void setRole(Role x){role=x;}public LocalDateTime getCreatedAt(){return createdAt;}}